-- DungeonMapDB: dungeon / raid maps for the world map's dungeon view.
-- GENERATED by tools/dungeonmaps_export.py from the ClassicDungeonMaps addon's
-- tables - don't edit by hand.
--
-- _maps[code][floor] = { name, path, ext, pins }: twelve 256px tiles
-- <path><1..12><ext> in a 4x3 grid. Most are the client's own
-- Interface\Worldmap tiles; dungeons that were later remade ship their
-- vanilla layout in assets/textures/dungeonmaps.
-- pin = { x, y (0-1 across the map), text, angle?, size?,
--         boss = creature display id | atlas = Blizzard atlas name,
--         link = { code, floor }? (click opens that floor), exit = true? }
-- _subzones[name] / _instances[name] = { code, floor }: minimap subzone text
-- and instance name with the spaces removed (enUS).

object "DungeonMapDB" {
    GetFloors = function(self, code)
        return self._maps[code]
    end;

    -- code, floor for a minimap subzone name / an instance name; nil when unknown.
    FindBySubzone = function(self, name)
        local hit = self._subzones[string.gsub(name or "", "%s+", "")]
        if hit then return hit[1], hit[2] end
    end;

    FindByInstance = function(self, name)
        local hit = self._instances[string.gsub(name or "", "%s+", "")]
        if hit then return hit[1], hit[2] end
    end;

